@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700;800&family=Space+Grotesk:wght@500;600;700&display=swap');
:root{--ink:#f7f7fb;--muted:#a3a6b8;--bg:#11131b;--panel:#1a1d28;--coral:#ff806d;--lilac:#a894ff;--green:#8ce4bb;--screen-ink:#20212b;--screen-muted:#777988;--screen-bg:#f5f4f1}
*{box-sizing:border-box}body{margin:0;color:var(--ink);font-family:'DM Sans',sans-serif;background:radial-gradient(ellipse at 50% 48%,#242334 0,transparent 56%),#11131b;min-height:100vh}button,input,textarea{font:inherit}button{cursor:pointer}.game-shell{max-width:1280px;margin:auto;padding:20px 52px 14px}.topbar{display:flex;align-items:center;justify-content:space-between;height:42px}.brand{display:flex;align-items:center;gap:10px;color:#fff;text-decoration:none;font:700 15px 'Space Grotesk',sans-serif;letter-spacing:1.6px}.brand-mark{color:var(--coral);font-size:20px;letter-spacing:-8px;margin-right:8px}.brand-light{font-weight:500;color:#a6a7b3}.top-meta,.sound-toggle{font-size:10px;letter-spacing:1.6px;color:#9da0ae}.top-meta{display:flex;align-items:center;gap:9px}.live-dot{height:6px;width:6px;border-radius:50%;background:#83e5b3;box-shadow:0 0 10px #83e5b3}.sound-toggle{background:#20222d;border:1px solid #343644;border-radius:20px;color:#e4e3ec;padding:8px 13px;font-size:12px;letter-spacing:0}.sound-toggle span{color:#a5a6b2;margin-left:4px}.intro{display:grid;grid-template-columns:1fr 380px;gap:45px;align-items:center;padding:32px 0 28px}.eyebrow{font-size:9px;letter-spacing:1.9px;color:#a6a8b7;font-weight:700;margin:0 0 9px}.intro h1{font:700 clamp(38px,4.7vw,57px)/.99 'Space Grotesk',sans-serif;letter-spacing:-2.8px;margin:0}.intro h1 span{color:var(--coral)}.intro-sub{color:#a6a8b5;font-size:13px;line-height:1.65;max-width:390px;margin:13px 0 0}.quest-card{background:linear-gradient(135deg,#242633,#1d202b);border:1px solid #393b4a;border-radius:17px;padding:15px 17px 12px;box-shadow:0 12px 35px #090a1035;position:relative}.quest-head{display:flex;align-items:center;gap:10px}.quest-icon{width:32px;height:32px;background:#39303b;border-radius:10px;display:grid;place-items:center;color:#ffaf8a;font-size:18px}.quest-head .eyebrow{font-size:8px;margin-bottom:3px}.quest-head strong{font:600 13px 'Space Grotesk',sans-serif}.quest-count{margin-left:auto;color:var(--green);font:600 11px 'Space Grotesk',sans-serif}.progress-track{height:4px;background:#383a48;border-radius:5px;margin:13px 0 10px;overflow:hidden}.progress-track i{height:100%;display:block;width:0;background:linear-gradient(90deg,#ff977d,#f9c17b);border-radius:5px;transition:width .45s}.quest-steps{display:grid;grid-template-columns:1fr 1fr;gap:5px 12px}.quest-step{font-size:10px;color:#9295a4;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.quest-step.done{color:#9ce7c1}.quest-step b{font-size:11px;margin-right:5px;color:#8b8d9c}.quest-step.done b{color:#93e5ba}.new-quest{position:absolute;right:13px;bottom:10px;border:0;background:none;color:#9b9eae;font-size:10px;padding:3px}.new-quest:hover{color:white}.stage-caption{display:flex;align-items:center;gap:11px;color:#828593;font-size:9px;letter-spacing:1.6px;margin:0 auto 15px;max-width:740px}.stage-caption span:last-child{letter-spacing:.3px;text-transform:none;font-size:11px;color:#a3a5b1}.caption-line{height:1px;background:#393a46;flex:1}.phones{display:flex;justify-content:center;align-items:flex-start;gap:27px;position:relative}.phone{width:316px;position:relative}.phone-frame{position:relative;background:linear-gradient(130deg,#d9dce6,#747988 7%,#171923 14%,#08090d 85%,#646978 96%,#c6c8d1);padding:7px;border-radius:42px;box-shadow:0 25px 55px #0008,0 0 0 1px #e0e1e726;transition:transform .35s}.phone:hover .phone-frame{transform:translateY(-3px)}.phone-screen{height:548px;position:relative;overflow:hidden;border-radius:36px;background:#c9bddc;color:var(--screen-ink);isolation:isolate}.wallpaper{position:absolute;inset:0;z-index:-1;overflow:hidden;background:linear-gradient(155deg,#ffb39e 0%,#d1a2c7 43%,#8d9bce 100%)}.wallpaper:before,.wallpaper:after{content:'';position:absolute;border-radius:50%;filter:blur(1px)}.wallpaper:before{width:340px;height:340px;left:-88px;top:147px;background:linear-gradient(140deg,#fbd4b2,#f9879a 62%,#ca7aa8);box-shadow:inset -23px -30px 60px #9b497a40}.wallpaper:after{width:330px;height:330px;right:-117px;top:-37px;background:linear-gradient(145deg,#ffe6bc,#f9aa9f 54%,#b07dc4);opacity:.83}.phone-right .wallpaper{background:linear-gradient(148deg,#a8cbce,#7892c8 48%,#a394c6)}.phone-right .wallpaper:before{width:380px;height:370px;left:-130px;top:185px;background:linear-gradient(135deg,#ddedc8,#91c6aa 52%,#59aab1)}.phone-right .wallpaper:after{right:-95px;top:-88px;background:linear-gradient(140deg,#f4d0b4,#e69fa5 55%,#a384c8)}.dynamic-island{position:absolute;z-index:8;top:9px;left:50%;transform:translateX(-50%);width:83px;height:24px;border-radius:20px;background:#090a0d}.island-camera{position:absolute;right:9px;top:8px;width:7px;height:7px;border-radius:50%;background:#1b2635;box-shadow:inset 0 0 3px #7689a9}.statusbar{height:36px;position:absolute;z-index:5;top:0;left:0;right:0;padding:9px 22px 0;display:flex;justify-content:space-between;color:#fff;font-size:10px;font-weight:700;text-shadow:0 1px 3px #3338;pointer-events:none}.status-icons{font-size:8px;letter-spacing:1px}.status-icons b{font-size:12px;vertical-align:-1px;margin:0 1px}.battery{width:16px;height:8px;display:inline-block;border:1px solid #fff;border-radius:2px;position:relative;margin-left:1px;vertical-align:0}.battery:after{content:'';position:absolute;right:-3px;top:2px;width:2px;height:3px;background:#fff}.battery i{display:block;width:70%;height:100%;background:#fff}.screen-content{position:absolute;inset:0;z-index:2;overflow:hidden;padding-top:37px}.home-indicator{position:absolute;z-index:10;bottom:5px;left:0;right:0;display:flex;justify-content:center;pointer-events:none}.home-indicator i{width:94px;height:4px;border-radius:5px;background:white;box-shadow:0 1px 3px #3337}.side-button{position:absolute;right:-3px;top:112px;width:3px;height:58px;background:#737886;border-radius:0 3px 3px 0}.phone-label{display:flex;align-items:center;justify-content:center;gap:6px;padding-top:10px;font-size:9px;letter-spacing:1.5px;color:#a5a6b3}.phone-label b{color:#fff}.phone-label-extra{letter-spacing:.1px;color:#777a89;font-size:10px;margin-left:3px}.phone-dot{width:6px;height:6px;border-radius:50%}.phone-dot.coral{background:var(--coral)}.phone-dot.lilac{background:var(--lilac)}.duo-link{position:absolute;top:44%;left:50%;transform:translate(-50%,-50%);z-index:4;display:flex;flex-direction:column;align-items:center;gap:5px;color:#c9bbff;text-shadow:0 0 14px #b08dff}.duo-link span{font-size:20px;background:#262439;border:1px solid #6b5b95;width:34px;height:34px;border-radius:50%;display:grid;place-items:center}.duo-link i{width:1px;height:17px;background:linear-gradient(#ad94ff,transparent)}.duo-link small{font-size:7px;letter-spacing:1px;color:#c4b8f5}footer{display:flex;justify-content:space-between;color:#727584;font-size:9px;letter-spacing:1.1px;padding:21px 0 3px}footer b{color:#aaa}.toast{position:fixed;z-index:30;bottom:24px;left:50%;transform:translate(-50%,15px);background:#f7f5f2;color:#23232d;padding:11px 17px;border-radius:25px;font-size:12px;font-weight:700;box-shadow:0 8px 25px #0006;opacity:0;pointer-events:none;transition:.3s}.toast.show{opacity:1;transform:translate(-50%,0)}.confetti-layer{position:fixed;inset:0;pointer-events:none;z-index:25;overflow:hidden}.confetti-piece{position:absolute;top:-15px;width:7px;height:11px;animation:fall 1.6s ease-in forwards}@keyframes fall{to{transform:translateY(105vh) rotate(680deg);opacity:.2}}
/* phone home screen */
.home-view{height:100%;padding:18px 17px 20px;position:relative;color:white;display:flex;flex-direction:column}.home-date{font:500 11px 'Space Grotesk',sans-serif;text-align:center;text-shadow:0 1px 4px #3337}.home-clock{font:500 52px/.98 'Space Grotesk',sans-serif;text-align:center;letter-spacing:-3px;text-shadow:0 2px 6px #4444;margin-top:3px}.home-widget{margin:15px 0 14px;background:#faf9f2d9;color:#292936;border:1px solid #ffffff80;border-radius:13px;padding:10px 12px;display:flex;align-items:center;justify-content:space-between;box-shadow:0 6px 16px #563e4b22;min-height:53px}.widget-kicker{font-size:8px;font-weight:700;letter-spacing:.8px;color:#777889}.widget-main{font-size:11px;font-weight:700;margin-top:3px}.widget-weather{font-size:21px}.app-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:12px 7px}.app-button{border:0;background:none;color:white;padding:0;min-width:0;text-align:center;display:flex;flex-direction:column;align-items:center;gap:4px;text-shadow:0 1px 4px #302b3b99}.app-icon{height:46px;width:46px;border-radius:13px;display:grid;place-items:center;font-size:22px;color:white;box-shadow:0 5px 10px #17182734,inset 0 1px 1px #ffffff80;transition:transform .15s,filter .15s}.app-button:hover .app-icon{transform:scale(1.09);filter:brightness(1.1)}.app-button:active .app-icon{transform:scale(.94)}.app-name{font-size:9px;font-weight:500;max-width:60px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.icon-messages{background:linear-gradient(145deg,#73e184,#26b95c)}.icon-safari{background:linear-gradient(145deg,#9ce9ff,#398eea)}.icon-notes{background:linear-gradient(145deg,#ffe17b,#e9a934)}.icon-camera{background:linear-gradient(145deg,#777986,#252833)}.icon-music{background:linear-gradient(145deg,#ff728e,#d13077)}.icon-maps{background:linear-gradient(145deg,#b7eb8e,#71b778)}.icon-weather{background:linear-gradient(145deg,#77bcff,#627de6)}.icon-calendar{background:linear-gradient(145deg,#fff,#e4e4eb);color:#f35d6e}.icon-calendar small{font-size:8px;font-weight:800;line-height:1;color:#f35d6e}.icon-photos{background:linear-gradient(145deg,#fff,#ddd);color:#f0717e}.icon-reminders{background:linear-gradient(145deg,#fff,#e2e2e7);color:#555}.icon-settings{background:linear-gradient(145deg,#b8c0cc,#707987)}.icon-appstore{background:linear-gradient(145deg,#64c9ff,#3479eb)}.app-dock{margin-top:auto;margin-bottom:10px;background:#fff4;border:1px solid #ffffff45;border-radius:20px;padding:8px 9px;display:flex;justify-content:space-between;gap:4px;backdrop-filter:blur(10px)}.app-dock .app-button{gap:0}.app-dock .app-name{display:none}.app-dock .app-icon{width:43px;height:43px;border-radius:12px}.home-folder{position:absolute;bottom:85px;right:18px;color:#fff;font-size:8px;text-shadow:0 1px 3px #333}.phone-right .home-widget{background:#f9fff0d9}.phone-header{display:flex;align-items:center;justify-content:space-between;padding:5px 17px 10px;position:relative;z-index:1}.phone-header button,.back-button{border:0;background:#ffffffa8;color:#393a48;width:28px;height:28px;border-radius:50%;font-size:16px;display:grid;place-items:center}.phone-header .header-title{font:700 14px 'Space Grotesk',sans-serif}.screen-app{height:100%;overflow:auto;background:var(--screen-bg);color:var(--screen-ink);padding-bottom:32px;scrollbar-width:none}.screen-app::-webkit-scrollbar{display:none}.app-body{padding:0 16px 18px}.app-kicker{font-size:9px;color:#858795;letter-spacing:1.1px;font-weight:700;margin:8px 0}.app-title{font:700 23px/1.1 'Space Grotesk',sans-serif;letter-spacing:-.7px;margin:3px 0 12px}.app-subtitle{font-size:11px;color:#777987;line-height:1.5}.soft-card{border:1px solid #e8e7e4;background:white;border-radius:13px;padding:12px;margin:9px 0;box-shadow:0 3px 10px #25253208}.primary-action{background:#24232e;color:white;border:0;border-radius:10px;padding:10px 13px;font-size:11px;font-weight:700;transition:transform .15s,background .15s}.primary-action:hover{background:#454254;transform:translateY(-1px)}.primary-action.coral-action{background:#f1746e}.primary-action.green-action{background:#39b66a}.pill{display:inline-flex;align-items:center;border-radius:20px;background:#eeedf3;padding:6px 9px;font-size:9px;color:#666875}.app-input,.app-textarea{width:100%;background:#fff;border:1px solid #e3e3e7;border-radius:10px;padding:10px;font-size:11px;color:#272833;outline:none}.app-input:focus,.app-textarea:focus{border-color:#9c8bff;box-shadow:0 0 0 3px #9c8bff22}.app-textarea{height:100px;resize:vertical;line-height:1.5}.nav-bar{position:absolute;top:42px;left:0;right:0;z-index:4;display:flex;align-items:center;justify-content:space-between;padding:0 13px}.nav-bar .back-button{background:#ffffffd9}.nav-title{font-size:11px;font-weight:700;background:#ffffffa8;border-radius:15px;padding:6px 11px}.phone-label{position:relative}
@media(max-width:850px){.game-shell{padding:16px 24px}.intro{grid-template-columns:1fr 340px;gap:25px}.phones{gap:22px}.phone{width:min(316px,42vw)}.phone-screen{height:530px}.phone-label-extra{display:none}.duo-link{left:50%}}
@media(max-width:650px){.game-shell{padding:12px 13px 10px}.top-meta{display:none}.intro{grid-template-columns:1fr;gap:17px;padding:23px 0 22px}.intro h1{font-size:41px}.intro-sub{max-width:430px}.quest-card{padding:12px 14px}.quest-steps{padding-bottom:10px}.stage-caption{margin-bottom:11px}.phones{gap:11px}.phone{width:calc(50vw - 22px);max-width:290px}.phone-frame{padding:5px;border-radius:32px}.phone-screen{height:clamp(395px,132vw,535px);border-radius:27px}.side-button{top:90px}.dynamic-island{top:7px;width:68px;height:20px}.island-camera{top:6px}.statusbar{padding:7px 13px 0;font-size:9px}.screen-content{padding-top:31px}.home-view{padding:16px 8px 14px}.home-clock{font-size:clamp(36px,12vw,48px)}.home-widget{padding:7px;margin:11px 0 12px;min-height:46px}.widget-main{font-size:9px}.widget-kicker{font-size:7px}.app-grid{gap:9px 2px}.app-icon{height:clamp(34px,11vw,43px);width:clamp(34px,11vw,43px);font-size:19px;border-radius:11px}.app-name{font-size:8px}.app-dock{padding:6px 5px;margin-bottom:7px;border-radius:15px}.app-dock .app-icon{height:clamp(32px,10.5vw,41px);width:clamp(32px,10.5vw,41px)}.phone-header{padding:4px 11px 8px}.phone-header .header-title{font-size:12px}.app-body{padding:0 10px 18px}.app-title{font-size:19px}.app-subtitle{font-size:10px}.soft-card{padding:9px;margin:7px 0}.app-input,.app-textarea{padding:8px;font-size:10px}.app-textarea{height:80px}.primary-action{padding:9px 10px;font-size:10px}.nav-bar{top:34px;padding:0 8px}.nav-title{font-size:10px}footer{font-size:8px;letter-spacing:.3px;padding-top:15px}footer span:nth-child(2){display:none}.phone-label{font-size:8px;letter-spacing:.8px;padding-top:7px}.duo-link{top:44%}.duo-link span{width:26px;height:26px;font-size:15px}.duo-link small{font-size:6px}}
@media(max-width:360px){.game-shell{padding-left:9px;padding-right:9px}.phones{gap:8px}.phone{width:calc(50vw - 18px)}.home-view{padding-left:5px;padding-right:5px}.app-grid{gap:8px 0}.app-name{font-size:7px}}

const apps = [
  {id:'messages',name:'Messages',icon:'●',tone:'messages',phone:1},
  {id:'safari',name:'Safari',icon:'◉',tone:'safari',phone:2},
  {id:'notes',name:'Notes',icon:'▤',tone:'notes',phone:1},
  {id:'camera',name:'Camera',icon:'◉',tone:'camera',phone:2},
  {id:'music',name:'Music',icon:'♫',tone:'music',phone:2},
  {id:'maps',name:'Maps',icon:'⌖',tone:'maps',phone:1},
  {id:'weather',name:'Weather',icon:'☀',tone:'weather',phone:1},
  {id:'calendar',name:'Calendar',icon:'',tone:'calendar',phone:1},
  {id:'photos',name:'Photos',icon:'✿',tone:'photos',phone:2},
  {id:'reminders',name:'Reminders',icon:'☷',tone:'reminders',phone:1},
  {id:'settings',name:'Settings',icon:'⚙',tone:'settings',phone:2},
  {id:'appstore',name:'App Store',icon:'A',tone:'appstore',phone:2}
];
const quests=[
 {title:'A day well connected',tasks:[['message','Send a message','Messages'],['note','Save a little note','Notes'],['web','Visit a website','Safari'],['music','Play a favorite','Music']]},
 {title:'Make some memories',tasks:[['photo','Take a photo','Camera'],['route','Plan a little outing','Maps'],['event','RSVP to a plan','Calendar'],['web','Explore the web','Safari']]},
 {title:'Your pocket-sized reset',tasks:[['weather','Check the forecast','Weather'],['reminder','Finish a reminder','Reminders'],['music','Play some music','Music'],['note','Write something down','Notes']]}
];
const state={quest:0,done:new Set(),open:{1:null,2:null},messages:[{from:'Mia',text:'Coffee and a walk today? ☀️',time:'9:38'}],notes:[],photos:[],song:0,playing:false,route:null,weatherF:false,reminders:[{text:'Pick up something lovely',done:false},{text:'Take a screen break',done:false}],calendarJoined:false,dark:false,wallpaper:false,sound:false};
const songs=[['Golden Hour','JVKE'],['Sunroof','Nicky Youre'],['Bloom','The Paper K ಕೆಲವು'],['Sunday Best','Surfaces']];
let toastTimer;
function timeNow(){return new Intl.DateTimeFormat('en',{hour:'numeric',minute:'2-digit'}).format(new Date())}
function showToast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2100)}
function setQuest(n){state.quest=n%quests.length;state.done.clear();renderQuest();showToast('A fresh little quest is ready ✦')}
function complete(key){if(state.done.has(key))return;state.done.add(key);renderQuest();const task=quests[state.quest].tasks.find(t=>t[0]===key);showToast(task?`Quest step complete: ${task[1]} ✓`:'Nice one — progress saved!');if(state.done.size===quests[state.quest].tasks.length){showToast('Duo quest complete! You make a great team ✨');celebrate()}}
function renderQuest(){const q=quests[state.quest];document.querySelector('#questTitle').textContent=q.title;document.querySelector('#questCount').textContent=`${state.done.size} / ${q.tasks.length}`;document.querySelector('#progressFill').style.width=`${state.done.size/q.tasks.length*100}%`;document.querySelector('#questSteps').innerHTML=q.tasks.map(([key,label,app])=>`<div class="quest-step ${state.done.has(key)?'done':''}"><b>${state.done.has(key)?'✓':'○'}</b>${label}</div>`).join('')}
function celebrate(){const layer=document.querySelector('#confetti');const colors=['#ff806d','#a894ff','#8ce4bb','#f8c46b','#fff'];for(let i=0;i<55;i++){const bit=document.createElement('i');bit.className='confetti-piece';bit.style.left=Math.random()*100+'%';bit.style.background=colors[i%colors.length];bit.style.animationDelay=Math.random()*.55+'s';bit.style.transform=`rotate(${Math.random()*180}deg)`;layer.append(bit);setTimeout(()=>bit.remove(),2300)}}
function iconMarkup(app){return `<button class="app-button" data-open="${app.id}" aria-label="Open ${app.name}"><span class="app-icon icon-${app.tone}">${app.id==='calendar'?'<small>FRI<br><b>07</b></small>':app.icon}</span><span class="app-name">${app.name}</span></button>`}
function home(phone){const dock=['messages','safari','music','camera'].map(id=>iconMarkup(apps.find(a=>a.id===id))).join('');const grid=apps.map(a=>iconMarkup(a)).join('');const copy=phone===1?'A lovely day to get things done.':'Your next little adventure awaits.';return `<div class="home-view"><div class="home-date">FRIDAY, NOVEMBER 7</div><div class="home-clock" data-clock>9:41</div><div class="home-widget"><div><div class="widget-kicker">${phone===1?'DUO QUEST':'A LITTLE WEATHER'}</div><div class="widget-main">${phone===1?'${state.done.size} of 4 steps done':copy}</div></div><div class="widget-weather">${phone===1?'✦':'☀️'}</div></div><div class="app-grid">${grid}</div><div class="home-folder">Extras</div><div class="app-dock">${dock}</div></div>`}
function renderHomes(){[1,2].forEach(p=>{const el=document.querySelector(`#content${p}`);if(!state.open[p])el.innerHTML=home(p);else el.innerHTML=renderApp(state.open[p],p);el.querySelectorAll('[data-open]').forEach(btn=>btn.addEventListener('click',()=>openApp(p,btn.dataset.open)));el.querySelectorAll('[data-action]').forEach(btn=>btn.addEventListener('click',()=>action(p,btn.dataset.action,btn)))});updateClock()}
function openApp(phone,id){state.open[phone]=id;renderHomes()}
function goHome(phone){state.open[phone]=null;renderHomes()}
function shell(phone,title,body){return `<div class="screen-app"><div class="phone-header"><button class="back-button" data-action="home" aria-label="Home">‹</button><span class="header-title">${title}</span><button class="back-button" data-action="home" aria-label="Close">⌂</button></div><div class="app-body">${body}</div></div>`}
function renderApp(id,phone){switch(id){
case'messages':return messageApp();case'notes':return notesApp();case'safari':return safariApp();case'music':return musicApp();case'maps':return mapsApp();case'camera':return cameraApp();case'weather':return weatherApp();case'calendar':return calendarApp();case'photos':return photosApp();case'reminders':return remindersApp();case'settings':return settingsApp();case'appstore':return storeApp();default:return home(phone)}}
function messageApp(){return shell(1,'Messages',`<div class="app-kicker">FRIENDS</div><h2 class="app-title">Good morning ☀️</h2><div class="chat-list">${state.messages.map(m=>`<div class="message-row"><div class="avatar">${m.from==='You'?'Y':'M'}</div><div class="chat-copy"><b>${m.from}</b><div>${escapeHtml(m.text)}</div></div><small>${m.time}</small></div>`).join('')}</div><div class="soft-card"><div class="app-kicker">QUICK REPLIES</div><div class="quick-replies"><button class="pill" data-action="reply-coffee">Absolutely! ☕</button><button class="pill" data-action="reply-walk">Let's do it 🚶</button><button class="pill" data-action="reply-later">Maybe later 💛</button></div></div><div class="compose"><input class="app-input" id="messageInput" placeholder="iMessage" maxlength="120"><button class="send-button" data-action="send-message" aria-label="Send">↑</button></div>`)}
function notesApp(){return shell(1,'Notes',`<div class="app-kicker">QUICK NOTE</div><h2 class="app-title">A thought for later.</h2><div class="soft-card"><input id="noteTitle" class="app-input" placeholder="Title your note" maxlength="35" value="${escapeAttr(state.noteDraftTitle||'')}"/><textarea id="noteText" class="app-textarea" placeholder="Start typing...">${escapeHtml(state.noteDraft||'')}</textarea><div class="note-actions"><span class="app-subtitle">${state.notes.length} saved note${state.notes.length===1?'':'s'}</span><button class="primary-action coral-action" data-action="save-note">Save note</button></div></div><div class="saved-notes">${state.notes.slice().reverse().map(n=>`<div class="soft-card saved-note"><b>📝 ${escapeHtml(n.title||'Untitled')}</b><p>${escapeHtml(n.text)}</p></div>`).join('')}</div>`)}
function safariApp(){return shell(2,'Safari',`<div class="app-kicker">THE WEB IS YOURS</div><h2 class="app-title">Where to today?</h2><form class="browser-form" id="browserForm"><span>⌕</span><input id="browserInput" class="app-input" placeholder="Search or enter a website" autocomplete="url"><button type="submit" aria-label="Go">↗</button></form><div class="app-kicker" style="margin-top:19px">QUICK EXPLORE</div><div class="site-grid"><button data-site="https://www.wikipedia.org"><b class="site-icon wiki">W</b><span>Wikipedia</span></button><button data-site="https://www.nasa.gov"><b class="site-icon nasa">NASA</b><span>NASA</span></button><button data-site="https://www.nationalgeographic.com"><b class="site-icon natgeo">N</b><span>Nat Geo</span></button><button data-site="https://www.metmuseum.org"><b class="site-icon met">M</b><span>The Met</span></button></div><div class="soft-card browser-hint"><b>Go anywhere.</b><p>Search the web, or enter a full website address. Links open in a new tab so your duo stays right here.</p><span class="pill">Real websites ↗</span></div><div id="searchResults"></div>`)}
function musicApp(){const [title,artist]=songs[state.song];return shell(2,'Music',`<div class="app-kicker">MADE FOR THIS MOMENT</div><h2 class="app-title">A little soundtrack.</h2><div class="album-art"><div class="album-orb"></div><span>DUO<br>RADIO</span></div><div class="track-info"><b>${title}</b><span>${artist}</span></div><div class="music-progress"><i class="${state.playing?'is-playing':''}"></i></div><div class="music-controls"><button data-action="prev-song" aria-label="Previous">↶</button><button class="play-button" data-action="toggle-play" aria-label="Play">${state.playing?'Ⅱ':'▶'}</button><button data-action="next-song" aria-label="Next">↷</button></div><div class="soft-card music-queue"><span>UP NEXT</span><b>${songs[(state.song+1)%songs.length][0]}</b><small>DUO MIX · ${songs.length} SONGS</small></div>`)}
const places=[['Little Fern Café','Coffee · 8 min walk','☕'],['Riverside Garden','Outdoors · 12 min walk','🌿'],['The Book Nook','Books · 5 min walk','📚']];
function mapsApp(){return shell(1,'Maps',`<div class="app-kicker">AROUND YOU</div><h2 class="app-title">Pick a destination.</h2><div class="map-art"><div class="map-road road-one"></div><div class="map-road road-two"></div><div class="map-road road-three"></div><span class="map-pin">⌖</span><span class="map-label">YOU ARE HERE</span><span class="map-park">GREEN PARK</span></div><div class="place-list">${places.map((p,i)=>`<button class="place-row ${state.route===i?'selected':''}" data-action="place-${i}"><span class="place-emoji">${p[2]}</span><span><b>${p[0]}</b><small>${p[1]}</small></span><i>›</i></button>`).join('')}</div>${state.route===null?'':`<div class="route-card"><b>Route ready · ${places[state.route][0]}</b><p>Head east on Willow Lane. You'll be there in a few minutes.</p><button class="primary-action green-action" data-action="start-route">${state.routeStarted?'End route':'Start walking'}</button></div>`}`)}
function cameraApp(){return shell(2,'Camera',`<div class="camera-app"><div class="camera-view"><div class="camera-sun"></div><div class="camera-hill hill-back"></div><div class="camera-hill hill-front"></div><div class="camera-caption">${state.photos.length?`Duo memory #${state.photos.length}`:'A moment worth keeping'}</div></div><div class="camera-tip">Tap the shutter to keep this little moment.</div><button class="shutter" data-action="shutter" aria-label="Take photo"><i></i></button><div class="camera-mini">${state.photos.length?`<span>▧ ${state.photos.length} saved</span><button data-action="open-photos">View photos ↗</button>`:'A sunny day, saved forever.'}</div></div>`)}
function weatherApp(){const value=state.weatherF?'73°':'23°';return shell(1,'Weather',`<div class="weather-hero"><div class="app-kicker">YOUR NEIGHBORHOOD</div><h2 class="weather-temp">${value}</h2><div class="weather-desc">Mostly sunny <span>☀️</span></div><div class="weather-place">Brooklyn, NY</div><div class="weather-high">H: ${state.weatherF?'77°':'25°'} &nbsp; L: ${state.weatherF?'64°':'18°'}</div></div><div class="soft-card forecast"><div class="app-kicker">THE NEXT FEW HOURS</div><div class="forecast-row">${[['NOW','☀️','23°'],['11 AM','🌤️','24°'],['12 PM','☀️','25°'],['1 PM','☀️','24°']].map(x=>`<span><small>${x[0]}</small><b>${x[1]}</b><i>${state.weatherF?Math.round((parseInt(x[2])-32)*9/5+32)+'°':x[2]}</i></span>`).join('')}</div></div><button class="primary-action" data-action="toggle-temp">Show in °${state.weatherF?'C':'F'}</button> <button class="pill" data-action="refresh-weather">↻ Refresh</button>`)}
function calendarApp(){return shell(1,'Calendar',`<div class="app-kicker">FRIDAY · NOVEMBER 7</div><h2 class="app-title">Good things ahead.</h2><div class="calendar-date"><span>FRI</span><b>07</b><small>NOVEMBER</small></div><div class="soft-card event-card"><div class="event-time">11:30 <small>AM</small></div><div class="event-divider"></div><div><b>Brunch & a catch-up</b><p>Little Fern Café · 2 guests</p><button class="${state.calendarJoined?'pill':'primary-action coral-action'}" data-action="rsvp">${state.calendarJoined?'✓ You’re going':'RSVP · Going?'}</button></div></div><div class="soft-card event-card"><div class="event-time">4:00 <small>PM</small></div><div class="event-divider purple"></div><div><b>Golden hour walk</b><p>Riverside Garden · Maybe</p><span class="pill">On your calendar</span></div></div>`)}
function photosApp(){return shell(2,'Photos',`<div class="app-kicker">YOUR LITTLE MOMENTS</div><h2 class="app-title">All the good stuff.</h2>${state.photos.length?`<div class="photo-grid">${state.photos.slice().reverse().map((p,i)=>`<div class="photo-tile tile-${i%4}"><span>${p.label}</span><small>${p.time}</small></div>`).join('')}</div>`:`<div class="empty-photos"><div>✿</div><b>Your memories live here.</b><p>Open Camera and tap the shutter to capture a little moment.</p><button class="primary-action" data-action="open-camera">Open Camera</button></div>`}`)}
function remindersApp(){return shell(1,'Reminders',`<div class="app-kicker">A FRIENDLY NUDGE</div><h2 class="app-title">Little things to do.</h2><div class="reminder-list">${state.reminders.map((r,i)=>`<button class="reminder-row ${r.done?'checked':''}" data-action="reminder-${i}"><span class="check-circle">${r.done?'✓':''}</span><span>${escapeHtml(r.text)}</span></button>`).join('')}</div><form id="reminderForm" class="reminder-form"><input id="reminderInput" class="app-input" placeholder="Add a reminder..." maxlength="48"><button class="primary-action">Add</button></form><p class="app-subtitle">Two minutes for yourself counts, too.</p>`)}
function settingsApp(){return shell(2,'Settings',`<div class="settings-profile"><div class="profile-avatar">D</div><div><b>Your Duo</b><p>Both phones, one team.</p></div></div><div class="app-kicker">PERSONALIZE</div><button class="setting-row" data-action="toggle-wallpaper"><span>🎨</span><span><b>Shared wallpaper</b><small>Let the phones match</small></span><i>${state.wallpaper?'ON':'OFF'}</i></button><button class="setting-row" data-action="toggle-dark"><span>🌙</span><span><b>Night mode</b><small>Make it a little cozier</small></span><i>${state.dark?'ON':'OFF'}</i></button><div class="app-kicker">ABOUT YOUR DUO</div><div class="soft-card about-card">DUO OS <span>Version 1.0 · Two is better than one.</span></div>`)}
function storeApp(){return shell(2,'App Store',`<div class="app-kicker">DISCOVER SOMETHING NEW</div><h2 class="app-title">Made for your day.</h2><div class="store-feature"><span>✦ DUO PICK OF THE DAY</span><b>Little Moments</b><p>Small ideas to make an ordinary day feel special.</p><button class="primary-action" data-action="get-app">${state.storeGot?'✓ Added to your Duo':'Get · Free'}</button><div class="store-art">✿</div></div><div class="app-kicker">ALREADY IN YOUR DUO</div><div class="soft-card store-app-row">🌦️ <b>Weather</b><span>OPEN</span></div><div class="soft-card store-app-row">🗺️ <b>Maps</b><span>OPEN</span></div>`)}

