function escapeHtml(value=''){return String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function escapeAttr(value=''){return escapeHtml(value)}
function updateClock(){const d=new Date();const clock=new Intl.DateTimeFormat('en',{hour:'numeric',minute:'2-digit'}).format(d);document.querySelectorAll('[data-clock]').forEach(e=>e.textContent=clock);const date=new Intl.DateTimeFormat('en',{weekday:'long',month:'long',day:'numeric'}).format(d).toUpperCase();document.querySelectorAll('.home-date').forEach(e=>e.textContent=date)}
function appendMessage(from,text){state.messages.push({from,text,time:timeNow()});if(state.messages.length>10)state.messages.shift();renderHomes()}
function safeUrl(raw){let value=raw.trim();if(!value)return null;if(!/^https?:\/\//i.test(value)){if(value.includes('.')&&!value.includes(' '))value='https://'+value;else return null}try{const u=new URL(value);return ['http:','https:'].includes(u.protocol)?u.href:null}catch{return null}}
function openExternal(url){const w=window.open(url,'_blank','noopener,noreferrer');if(!w)showToast('Allow pop-ups to open this website.');else showToast('Opening a real website in a new tab ↗')}
function action(phone,name,button){
 if(name==='home'){goHome(phone);return}
 if(name.startsWith('reply-')){const replies={'reply-coffee':'Absolutely! Coffee sounds perfect ☕','reply-walk':'Let’s do it! See you soon 🚶','reply-later':'Maybe later? I’ll let you know 💛'};appendMessage('You',replies[name]);complete('message');return}
 if(name==='send-message'){const input=document.querySelector('#messageInput');if(input&&input.value.trim()){const text=input.value.trim();appendMessage('You',text);complete('message')}else showToast('Write a little message first');return}
 if(name==='save-note'){const text=document.querySelector('#noteText')?.value.trim()||'';const title=document.querySelector('#noteTitle')?.value.trim()||'A little thought';if(!text){showToast('Add a thought before saving ✍️');return}state.notes.push({title,text});state.noteDraft='';state.noteDraftTitle='';complete('note');renderHomes();return}
 if(name==='toggle-play'){state.playing=!state.playing;if(state.playing)complete('music');renderHomes();soundPing();return}
 if(name==='next-song'||name==='prev-song'){state.song=(state.song+(name==='next-song'?1:songs.length-1))%songs.length;state.playing=true;renderHomes();return}
 if(name.startsWith('place-')){state.route=Number(name.split('-')[1]);state.routeStarted=false;renderHomes();return}
 if(name==='start-route'){if(!state.routeStarted){state.routeStarted=true;complete('route');showToast(`Walking route started to ${places[state.route][0]} 🧭`)}else{state.routeStarted=false;showToast('Route ended. Nice little walk!')}renderHomes();return}
 if(name==='shutter'){state.photos.push({label:['A sunny little moment','Good things, lately','A day to remember','Duo memory'][state.photos.length%4],time:timeNow()});complete('photo');renderHomes();soundPing();return}
 if(name==='open-photos'){openApp(phone,'photos');return}if(name==='open-camera'){openApp(phone,'camera');return}
 if(name==='toggle-temp'){state.weatherF=!state.weatherF;complete('weather');renderHomes();return}
 if(name==='refresh-weather'){complete('weather');showToast('Forecast is looking lovely ☀️');return}
 if(name==='rsvp'){state.calendarJoined=!state.calendarJoined;if(state.calendarJoined)complete('event');renderHomes();return}
 if(name.startsWith('reminder-')){const i=Number(name.split('-')[1]);state.reminders[i].done=!state.reminders[i].done;if(state.reminders[i].done)complete('reminder');renderHomes();return}
 if(name==='toggle-wallpaper'){state.wallpaper=!state.wallpaper;document.querySelectorAll('.phone-screen').forEach(e=>e.classList.toggle('shared-wallpaper',state.wallpaper));renderHomes();showToast(state.wallpaper?'Your phones are in sync 🎨':'Original wallpapers restored');return}
 if(name==='toggle-dark'){state.dark=!state.dark;document.querySelectorAll('.phone-screen').forEach(e=>e.classList.toggle('dark-mode',state.dark));renderHomes();showToast(state.dark?'Cozy night mode on 🌙':'Night mode off');return}
 if(name==='get-app'){state.storeGot=true;showToast('Little Moments added to your Duo ✦');renderHomes();return}
}
function soundPing(){if(!state.sound)return;try{const C=window.AudioContext||window.webkitAudioContext;const ctx=new C();const osc=ctx.createOscillator(),gain=ctx.createGain();osc.type='sine';osc.frequency.value=660;gain.gain.setValueAtTime(.035,ctx.currentTime);gain.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+.12);osc.connect(gain);gain.connect(ctx.destination);osc.start();osc.stop(ctx.currentTime+.12);osc.onended=()=>ctx.close()}catch{}}
document.addEventListener('click',e=>{
 const actionButton=e.target.closest('[data-action]');if(actionButton){const screen=actionButton.closest('.phone');if(screen)action(Number(screen.dataset.phone),actionButton.dataset.action,actionButton);return}
 const site=e.target.closest('[data-site]');if(site){complete('web');openExternal(site.dataset.site);return}
 const result=e.target.closest('[data-external]');if(result){complete('web');openExternal(result.dataset.external)}
});
document.addEventListener('submit',e=>{
 if(e.target.id==='browserForm'){e.preventDefault();const input=document.querySelector('#browserInput');const q=input.value.trim();if(!q){input.focus();return}let url=safeUrl(q);complete('web');if(url){document.querySelector('#searchResults').innerHTML=`<div class="soft-card"><div class="app-kicker">READY TO GO</div><b style="font-size:10px;overflow-wrap:anywhere">${escapeHtml(url)}</b><p class="app-subtitle">This is a real website. Open it in a new tab?</p><button class="primary-action" data-external="${escapeAttr(url)}">Open website ↗</button></div>`;return}const encoded=encodeURIComponent(q);document.querySelector('#searchResults').innerHTML=`<div class="app-kicker" style="margin-top:12px">SEARCH THE WEB</div><a class="search-result" href="https://www.google.com/search?q=${encoded}" target="_blank" rel="noopener noreferrer" data-external="https://www.google.com/search?q=${encoded}"><b>Search “${escapeHtml(q)}” ↗</b><small>Open results on Google</small></a><a class="search-result" href="https://en.wikipedia.org/w/index.php?search=${encoded}" target="_blank" rel="noopener noreferrer" data-external="https://en.wikipedia.org/w/index.php?search=${encoded}"><b>Look it up on Wikipedia ↗</b><small>Search the free encyclopedia</small></a>`;showToast('Here are a couple of real web searches ↗');return}
 if(e.target.id==='reminderForm'){e.preventDefault();const input=document.querySelector('#reminderInput');if(!input.value.trim())return;state.reminders.push({text:input.value.trim(),done:false});renderHomes()}
});
document.querySelector('#newQuest').addEventListener('click',()=>setQuest(state.quest+1));document.querySelector('#soundToggle').addEventListener('click',e=>{state.sound=!state.sound;e.currentTarget.innerHTML=state.sound?'♫ <span>Sound on</span>':'♫ <span>Sound off</span>';showToast(state.sound?'Sound on — taps have a little chime':'Sound off')});
document.querySelectorAll('.phone-screen').forEach(e=>{e.addEventListener('input',event=>{if(event.target.id==='noteText')state.noteDraft=event.target.value;if(event.target.id==='noteTitle')state.noteDraftTitle=event.target.value})});
renderQuest();renderHomes();setInterval(updateClock,30000);

